mapper.select:
SELECT
USER_ID AS userId
FROM users
WHERE USER_ID = #{userId}
AND USER_PWD = #{pwd}

mapper.update:
UPDATE users
SET USER_PWD = #{newPwd}
WHERE USER_ID = #{userId}

UPDATE pet
SET
PET_NAME = #{petName},
SPECIES = #{species},
BREED = #{breed},
BIRTHDATE = #{birthdate},
GENDER = #{gender}
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.delete:
DELETE FROM pet
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.update:
UPDATE pet
SET IS_MAIN = 'N'
WHERE USER_ID = #{userId}

UPDATE pet
SET IS_MAIN = 'Y'
WHERE PET_NO = #{petNo}
AND USER_ID = #{userId}

mapper.insert:
INSERT INTO pet_weight (
PET_NO,
WEIGHT
) VALUES (
#{petNo},
#{weight}
)

mapper.update:
UPDATE subscription
SET IS_AUTO = #{isAuto}
WHERE USER_ID = #{userId}
AND SUB_NO = #{subNo}
AND DATE_SUB(N_DATE, INTERVAL 1 DAY) >= NOW()
